// Node: Golden questions  (Workflow 7, JavaScript, Run Once for All Items)
// Fixed test set for the weekly quality check. Each question has an expected source
// (file name prefix) and key facts, or the expectation that the assistant hands off.
// Change this list when the knowledge base changes.
const QUESTIONS = [
  { id: 'Q01', question: 'How do I request vacation?', expect: 'answer', source: 'hr-leave', facts: ['personio'] },
  { id: 'Q02', question: 'How many vacation days do full-time employees get per year?', expect: 'answer', source: 'hr-leave', facts: ['30'] },
  { id: 'Q03', question: 'What happens if I am sick for more than six weeks?', expect: 'answer', source: 'hr-sickness', facts: ['krankengeld'] },
  { id: 'Q04', question: 'How long must my break be after 6 hours of work?', expect: 'answer', source: 'hr-working-time', facts: ['30'] },
  { id: 'Q05', question: 'How do I report a violation of the code of conduct?', expect: 'answer', source: 'hr-code-of-conduct', facts: ['speakup'] },
  { id: 'Q06', question: 'How do I set up the VPN?', expect: 'answer', source: 'it-vpn', facts: ['globalprotect'] },
  { id: 'Q07', question: 'When do I get my payslip?', expect: 'answer', source: 'finance-payroll', facts: ['25'] },
  { id: 'Q08', question: 'Which online courses must I complete in my first week?', expect: 'answer', source: 'onboarding-training', facts: ['gdpr', 'datenschutz', 'security', 'sicherheit'] },
  { id: 'Q09', question: 'Can I bring my dog to the office?', expect: 'handoff' },
  { id: 'Q10', question: 'What will my salary be next year?', expect: 'handoff' },
];

const run = String($execution.id);
return QUESTIONS.map((q, i) => ({ json: {
  ...q,
  run_id: run,
  sessionId: `qc-${run}-${i + 1}`,
} }));

// Node: Score answers  (Workflow 7, JavaScript, Run Once for All Items)
// Compares each reply with its expectation. Pairs replies with questions by position.
const HANDOFF_START = 'i could not find a reliable answer';
const qs = $('Golden questions').all().map(i => i.json);
const rs = $input.all().map(i => i.json);

const results = qs.map((q, i) => {
  const r = rs[i] || {};
  const reply = String(r.output ?? r.text ?? r.reply ?? '').trim();
  const low = reply.toLowerCase();
  let passed = false;
  let detail = '';
  if (!reply) {
    detail = 'no reply (' + String((r.error && (r.error.message || r.error)) || 'empty response').slice(0, 120) + ')';
  } else if (q.expect === 'handoff') {
    passed = low.startsWith(HANDOFF_START);
    detail = passed ? 'handed off as expected' : 'answered although no document covers it';
  } else if (low.startsWith(HANDOFF_START)) {
    detail = 'handed off although the document exists';
  } else if (!low.includes('[' + q.source)) {
    const cited = (reply.match(/\[[^\]]+\]/g) || []).join(' ') || 'none';
    detail = `wrong or missing source, cited ${cited}`;
  } else if (!(q.facts || []).some(f => low.includes(f))) {
    detail = 'right source, key fact missing (' + q.facts.join(' or ') + ')';
  } else {
    passed = true;
    detail = 'right source and key fact';
  }
  return { id: q.id, question: q.question, expected: q.expect === 'handoff' ? 'handoff' : q.source,
    reply: reply.slice(0, 1000), passed, detail };
});

const passedCount = results.filter(r => r.passed).length;
return [{ json: {
  total: results.length,
  passed: passedCount,
  score: Math.round(100 * passedCount / Math.max(results.length, 1)),
  failures: results.filter(r => !r.passed),
  results_json: JSON.stringify(results),
} }];

// Node: Build report  (Workflow 7, JavaScript, Run Once for All Items)
// Weekly report for People Ops: automatic score, failed questions, and 5 real answers
// from the past week for a human to check against the cited documents.
const s = $('Score answers').first().json;
const passMark = Number($('Config').first().json.pass_mark || 80);
const samples = $input.all().map(i => i.json).filter(r => r.question);

const lines = [];
lines.push(`**Weekly answer quality check: ${s.score}% (${s.passed} of ${s.total})**`);
lines.push(s.score >= passMark
  ? `At or above the ${passMark}% pass mark.`
  : `BELOW the ${passMark}% pass mark. Review the failures before employees rely on the assistant.`);
if (s.failures.length) {
  lines.push('Failed:');
  for (const f of s.failures) lines.push(`- ${f.id} ${f.question} -> ${f.detail}`);
}
if (samples.length) {
  lines.push('', 'Human review: check these real answers from the last 7 days against the cited documents:');
  samples.forEach((r, i) => lines.push(`${i + 1}. Q: ${r.question}\n   A: ${r.answer} (${r.sources || 'no source'})`));
}
let msg = lines.join('\n');
if (msg.length > 1900) msg = msg.slice(0, 1897) + '...';
return [{ json: { discord_message: msg, score: s.score, below_pass_mark: s.score < passMark } }];

parameters.query:
insert into automation_log (workflow, step, status, detail)
values ('wf7', 'quality_check', $1, $2)
returning id;
